IB_MAX_CFLOW_START=function() end IB_MAX_CFLOW_END=function() end IB_INLINING_START=function() end local function c(c,i)IB_INLINING_START(true)return c+i end local function i(c,i)IB_INLINING_START(true)return c*i,c/i end local function a(c)IB_MAX_CFLOW_START()local i if c<0 then i="negative"elseif c==0 then i="zero"elseif c%2==0 then i="even"else i="odd"end IB_MAX_CFLOW_END()return i end local D=0 for i=1,10,1 do D=c(D,i)end print("total",D)for c,i in ipairs({-3;0,4;7})do print(i,a(i))end local N,v=i(12,5)print(N,v)print(select("#",i(1,2)))